import {BURIAL_LINES,FINALE_TRAINERS,PEACH_FINAL,GALLERY_WORKS,COMMISSIONS} from './finale-data.js?v=0.90.52';
import {finaleState,finaleUnlocked,peachQuest,acceptPeachQuest,readPeachClue,turnOathRune,turnBridgeWeight,finalUniqueEncounter,canFightFinale,createCommission,settleFinalLeader} from './finale-rules.js?v=0.90.52';
const clues={guan:'Shelter the traveller first. Keep faith when the road is empty. Hold the crossing last. Touch the three named seals in the order of the promise. Defeat the requisitioner before approaching the guardian.',fei:'Three windlasses hold the old bridge. The west needs one turn, the middle three, and the east two. Each dial has four positions: 0, 1, 2, 3, then 0 again. The toll captain must release the crossing first.'};
export function handleFinale(id,a){const {state:s,room,line,showDialogue,warp,rewardTransaction:commit,buildMarkers,openModal,closeModal,escapeHTML:e,challengeTrainer,startWild,species,$}=a,q=finaleState(s),say=(n,t,p)=>showDialogue([line(n,t,p)]),gate=a.AREA_GATES[room]?.find(g=>g.id===id);
 if(gate?.action==='finale-entry'){if(!finaleUnlocked(s))say('Walter','Come back to Pate and Trade on the platform. We must see them cared for before leaving.','CHR-AERIC');else showDialogue([line('Walter','I have arranged a wagon. There is an old tree above the river, away from the road. I will meet you there.','CHR-AERIC')],()=>void warp(gate.to,...gate.arrival));return true;}
 if(gate?.action==='finale-gate'){
  if(room==='burialGrove'&&id.endsWith('-forward')&&!q.buried){say('Walter','Stay a little longer. We have not said goodbye.','CHR-AERIC');return true;}
  if(id==='cayfen-forward'&&!s.fates?.['LDR-07']){say('Cayfen watch','The marshal knows the old roads. Speak to him in Sun Hall before crossing Sporefall.');return true;}
  if(id==='sporeCrown-forward'&&!q.dariusDefeated){say('The last crossing','Darius and Cruxwyrm hold the way to Ramelle. Speak to Hasan, then stand beside him.');return true;}
  if(room==='burialGrove'&&q.legacies)commit(()=>{q.legacyDepartureSeen=true;});void warp(gate.to,...gate.arrival);return true;
 }
 if(id.startsWith('fn-rare-record-')){const key=id.slice(15);if(!['suncub','gehennuar'].includes(key))return false;if(!s.fates?.['LDR-07']){say('A sealed field record','Cayfen’s watch asks travellers to consult Marshal Ibrahim before approaching the rare guardians.');return true;}commit(()=>{q.rareRecords??=[];if(!q.rareRecords.includes(key))q.rareRecords.push(key);});say('The keeper’s field record',key==='suncub'?'A Suncub shelters beneath the terrace trees, away from the marching columns. It can grow into Cehong. The keeper asks visitors to approach quietly and leave it room to refuse. This is a single living creature, not a repeatable sighting.':'Gehennuar has climbed from the deep faults into Sporefall’s warm roots. The warden marked its shelf beside this record. The watcher is unique: once befriended or killed, it will not return.');buildMarkers();return true;}
 if(id.startsWith('fn-rare-encounter-')){const key=id.slice(18),encounter=finalUniqueEncounter(s,key),spec=PEACH_FINAL[key];if(!spec)return false;if(!encounter){say(spec.name,q.unique[key]?'This unique encounter is already recorded.':'Read the nearby keeper’s record after resolving Cayfen. A guardian already among your living or lost companions cannot appear again.');return true;}showDialogue([{...line(spec.name,'The guardian watches you from its shelter. Give it space while you prepare.'),choices:[{text:'Approach '+spec.name+'.',action:()=>startWild(encounter)},{text:'Leave it in peace.',action:()=>{}}]}]);return true;}
 if(id==='fn-burial'){if(!q.buried)a.burial();else say('Walter','We can come back whenever you need to. The road does not take this place away.','CHR-AERIC');return true;}
 if(id==='fn-pate-grave'||id==='fn-trade-grave'){say(id.includes('pate')?'Peter “Pate” FitzRobert':'Thomas “Trade” de Clare',id.includes('pate')?'You remember the way he slowed his steps without admitting it. The grass is beginning to settle around his stone.':'His notebook is safe in your pack. You remember him waiting for you to finish a question.');return true;}
 for(const key of ['guan','fei']){
  if(id==='fn-'+key+'-keeper'){const p=peachQuest(s,key);showDialogue([{...line(key==='guan'?'Crossing keeper':'Bridge keeper',p.accepted?'The side path is marked beside the river. Read the inscription, deal with the company at the crossing, then restore the old mechanism.':key==='guan'?'They are stripping metal from a guardian’s shrine. Travellers still shelter there. Will you help us keep the old promise?':'The captain has trapped families on the wrong side of the bridge. The old windlasses can hold it if we can reach them.'),choices:[{text:p.accepted?'I will keep looking.':'I will help.',action:()=>{commit(()=>acceptPeachQuest(s,key));buildMarkers();}},{text:'Not yet.',action:()=>{}}]}]);return true;}
  if(id==='fn-'+key+'-clue'){commit(()=>readPeachClue(s,key));say('The crossing inscription',peachQuest(s,key).accepted?clues[key]:'Speak to the keeper on Willowmere’s main road before disturbing the mechanism.');return true;}
  if(id==='fn-'+key+'-encounter'){const encounter=finalUniqueEncounter(s,key);if(!encounter){const p=peachQuest(s,key);say(PEACH_FINAL[key].name,q.unique[key]?'This unique encounter is already recorded. The shrine will not call another life.':!p.accepted?'Speak to the crossing keeper first.':!p.solved?'The old mechanism is not restored. Read its inscription.':'The company still holds this crossing. Defeat its captain.');return true;}showDialogue([{...line(PEACH_FINAL[key].name,'The guardian leaves its shelter and watches your expedition. It waits while you decide whether to approach.'),choices:[{text:'Approach '+PEACH_FINAL[key].name+'.',action:()=>startWild(encounter)},{text:'Prepare first.',action:()=>a.clearScene()}]}]);return true;}
 }
 if(id.startsWith('fn-guan-rune-')){let changed=false;commit(()=>{changed=turnOathRune(s,id.slice(13));});const p=peachQuest(s,'guan');say('The three oath seals',p.solved?'The seals settle. The old vow is restored.':!changed?'Read the inscription after accepting the keeper’s request.':'The seals sound: '+p.order.join(' → ')+(p.order.length===3?'. The promise does not hold. Start again.':'.'));buildMarkers();return true;}
 if(id.startsWith('fn-fei-weight-')){commit(()=>turnBridgeWeight(s,Number(id.at(-1))));const p=peachQuest(s,'fei');say('Bridge windlasses',p.solved?'The bridge settles firmly into its supports.':!p.read?'Read the bridgekeeper’s tally first.':'West '+p.weights[0]+' · Middle '+p.weights[1]+' · East '+p.weights[2]+'.');buildMarkers();return true;}
 const trainer=FINALE_TRAINERS.find(t=>t.id===id);
 if(trainer){if(s.fates?.[id]==='EXECUTED'){say('The empty hall','The leader’s fate is recorded.');return true;}if(s.fates?.[id]==='SPARED'){a.rematch(trainer);return true;}if(!canFightFinale(s,id)){say('The road ahead',id==='LDR-08'?'Stand beside Hasan against Darius at the last crossing first.':id==='LDR-07'?'Return to Walter beneath the old tree first.':'Speak to the crossing keeper before challenging this company.');return true;}challengeTrainer(trainer);return true;}
 if(id==='fn-darius'||id==='fn-hasan-ally'){if(q.dariusDefeated){say('Hasan','Ramelle is beyond the crossing. When you are ready, come to my fortress. I will show you what lies beneath it.','LDR-08');return true;}a.scene('darius');showDialogue([line('Sporefall','First Light and Dawnbloom soldiers stagger back together. Ahead, Cruxwyrm drives a company off the crossing. Hasan stands between the wounded and Darius.'),line('Darius','I watched them bury their children and go back for another banner. They will never stop. Not while there is anyone left to teach the next war.','REV-DARIUS-FINAL'),line('Aimon','Those people behind you are trying to get away.','CHR-AIMON'),line('Darius','And where will their children march when they grow up?','REV-DARIUS-FINAL'),line('Hasan','Aimon. Beside me. We hold this crossing together.','LDR-08'),{...line('The last crossing','Aimon and Hasan face two active opponents at a time. Darius’s company is trained in the upper nineties; Cruxwyrm is level 102.'),choices:[{text:'Stand beside Hasan.',action:()=>{a.clearScene();a.doubleBattle();}},{text:'Prepare first.',action:()=>a.clearScene()}]}]);return true;}
 if(id==='fn-crux-encounter'){const encounter=finalUniqueEncounter(s,'crux');if(!encounter)say('Cruxwyrm',q.unique.crux?'Cruxwyrm’s unique fate is recorded.':q.dariusDefeated?'The crossing has already recorded this sovereign among your living or lost partners.':'Darius’s control has not been broken.');else showDialogue([{...line('Cruxwyrm','The steel sovereign lowers its wings. Without Darius’s commands, it watches you in silence.'),choices:[{text:'Approach Cruxwyrm.',action:()=>startWild(encounter)},{text:'Prepare first.',action:()=>a.clearScene()}]}]);return true;}
 if(id.startsWith('fn-gallery-')&&GALLERY_WORKS.some(w=>'fn-gallery-'+w.id===id)){const w=GALLERY_WORKS.find(w=>'fn-gallery-'+w.id===id);commit(()=>{if(!q.gallerySeen.includes(w.id))q.gallerySeen.push(w.id);});openModal(w.title,`<img class="finale-painting" src="assets/finale/gallery-${w.id}.webp" alt="${e(w.title)}"><p><b>${e(w.artist)}</b></p><p>${e(w.text)}</p>`);return true;}
 if(['fn-art-commission','fn-gallery-curator','fn-gallery-collection'].includes(id)){if(id==='fn-gallery-collection'){showCollection(a);return true;}openModal('The Shared Hand',`<p>People and Abyssals work here together. Choose a living partner and make a picture for one of the town’s commissions.</p><div class="modal-actions"><button id="fn-create" class="primary">Create with a partner</button><button id="fn-collection">Your collection · ${q.commissions.length}</button></div>`);$('#fn-create').onclick=()=>commissionPartner(a);$('#fn-collection').onclick=()=>showCollection(a);return true;}
 if(id==='fn-inn-rest'){showDialogue([line('The innkeeper','There is a room ready. Rest as long as you need; your living partners can recover here.')],()=>{a.rest();});return true;}
 if(id==='fn-fortress-below'){if(!q.gateRevealed)say('The old stair','Hasan has promised to show you the way below after your formal challenge.');else if(!q.mirrorArrivalSeen)void a.descent(s.fates?.['LDR-08']);else void warp('afterlifeThreshold',24,24,'up');return true;}
 if(id==='fn-afterlife'){if(q.mirrorArrivalSeen){say('Severin Vale','The way is open, Aimon. You may prepare above, but the dead have not stopped moving beyond this door.');return true;}showDialogue([line('The answering mirror','The glass reflects the chamber, but not quite the people standing in it. Beyond the surface is a road without a sky.'),line('Aimon','Pate. Trade. If you’re there, I’m coming.','CHR-AIMON'),line('Walter','I am here with you. We will learn what this asks of us before we step through.','CHR-AERIC'),line('The threshold','The way into the afterlife has been found. The descent and its wardens begin in the next arc. You can still return to the living world.')],()=>{commit(()=>{q.thresholdSeen=true;});buildMarkers();});return true;}

 const errands={
  'fn-cayfen-courier':{name:'Canvas courier',story:'A travelling painter needs a covering that will protect a fresh river wash on the windy road. Which material should go closest to the wet canvas?',choices:['Dry spacer frame','Rough wool blanket','Dusty grain sack'],answer:0,reward:350,food:1,thanks:'You keep the fabric off the wet pigment. The courier leaves safely for the next village.'},
  'fn-cayfen-chimes':{name:'Bell-maker',story:'A family has asked for a quiet memorial chime. Which metal will give a gentle, lingering tone?',choices:['Cracked iron','Thin bronze','Loose stone'],answer:1,reward:280,food:0,thanks:'The bronze note carries across the studio square without drowning the voices.'},
  'fn-ramelle-medic':{name:'Sanctuary aide',story:'An exhausted traveller arrives from Sporefall, chilled and thirsty. Which should the sanctuary give them first?',choices:['Clean water and a warm seat','A combat tonic','A forced march'],answer:0,reward:420,food:1,thanks:'The traveller drinks slowly. Their hands stop trembling before you leave.'},
  'fn-ramelle-archivist':{name:'Vault archivist',story:'Two older carvings are identical except for later faction marks. Which record should be preserved?',choices:['Only Dawn Bloom’s','Only True Light’s','Both, with the difference recorded'],answer:2,reward:360,food:0,thanks:'The archivist makes two careful copies and files the difference without judgement.'}
 };
 if(errands[id]){const task=errands[id];q.townErrands??={};if(q.townErrands[id]){say(task.name,task.thanks);return true;}
  openModal(task.name,`<p>${e(task.story)}</p><div class="learning-choices">${task.choices.map((opt,i)=>`<button data-fn-errand="${i}">${e(opt)}</button>`).join('')}</div>`);
  document.querySelectorAll('[data-fn-errand]').forEach(button=>button.onclick=()=>{const right=+button.dataset.fnErrand===task.answer;closeModal();if(!right){say(task.name,'Not quite. Look again at what the task actually needs. You can try again.');return;}let done=false;if(!commit(()=>{if(!q.townErrands[id]){q.townErrands[id]=true;s.money=(s.money||0)+task.reward;s.fortifiedRations=(s.fortifiedRations||0)+task.food;done=true;}}))return;buildMarkers();say(task.name,task.thanks+(done?' You are paid '+task.reward+' doubloons'+(task.food?' and given a Fortified Ration.':'.'):''));});return true;
 }
 const accounts={
 'fn-road-sign':['Willowmere waystone','East: Remembering Tree, Silverwater Crossing, Flowering Terraces, Cayfen. The side paths after the tree lead to the Peach Grove guardians.'],
 'fn-cayfen-resident':['A mosaic apprentice','We repair a little of the square every morning. People still need somewhere beautiful to come home to.'],
 'fn-cayfen-painter':['A street painter','My partner chooses the colours. I used to correct her. The work got better when I stopped.'],
 'fn-cayfen-records':['The mirror records','A caravan account describes a mirror in chambers older than Ramelle’s fortress. Its custodian is Hasan. The account speaks of voices, not a promise of return.'],
 'fn-spore-lichen':['The lichen surveyor','The moonpool is safe on its high shelf. Under that glow, you can find Abyssals that avoid the military road.'],
 'fn-spore-herbalist':['The canopy herbalist','The high roots are older than the timber crossing. We tend the fungi here without disturbing their hosts.'],
 'fn-spore-moonpool':['The moonpool inscription','A shallow pool reflects the sky that the chasm cannot see. Old travellers rested here before there were banners.'],
 'fn-spore-bridge-notes':['The crossing diary','Two families left one another blankets here. The records do not say which army each belonged to.'],
 'fn-spore-sign':['The shelf markers','Pale roots mark the crossings. Follow the intact shelves; the black pools and broken edges cannot carry you. Two companies were driven back from the last bridge.'],
 'fn-spore-refugee':['A First Light medic','We lowered our weapons. The dragon kept coming. A Dawnbloom officer stayed to get us out. I don’t even know his name.'],
 'fn-wounded-bloom':['A Dawnbloom soldier','Hasan is still up there. He told us to bring the wounded down. All the wounded.'],
 'fn-wounded-first':['A First Light soldier','He said we were the last ones. Then he started talking about the children back home. Please stop him.'],
 'fn-ramelle-resident':['Water garden keeper','The channels have to be cleared every week. People arrive expecting a holy city to look after itself. It is still a place where people live.'],
 'fn-ramelle-child':['A child with chalk','My dragon has six wings. The real one has more. I ran out of space.'],
 'fn-sanctuary-keeper':['Sanctuary keeper','There is water, clean linen and somewhere quiet to sit. You don’t have to tell us which army brought you here.'],
 'fn-threshold-walter':['Walter','A story was all I had under that tree. Now we have a door. I still will not pretend to know what waits on its other side.']};
 if(accounts[id]){say(...accounts[id],id==='fn-threshold-walter'?'CHR-AERIC':undefined);return true;}return false;
}
function commissionPartner(a){const {state:s,openModal,escapeHTML:e,$}=a;openModal('Choose your artist',`<p>Choose a partner, then match the commission’s colours, composition and technique. Water, Ice and Grass partners favour river colours; Fire, Electric and Fairy favour sunset; Ground, Rock and Steel favour earth tones. A matching affinity adds 100 doubloons. Your partner’s mark and name will be part of the finished work.</p><div class="finale-artist-list">${s.party.filter(u=>u.hp>0&&!u.dead).map(u=>`<button data-fn-artist="${e(u.uid)}"><img src="${a.art(u)}" alt=""><b>${e(u.nickname||u.species.name)}</b><span>${e(u.species.types.join(' / '))}</span></button>`).join('')}</div>`);document.querySelectorAll('[data-fn-artist]').forEach(b=>b.onclick=()=>commissionChoices(a,b.dataset.fnArtist));}
function commissionChoices(a,uid,choices={}){const {state:s,openModal,escapeHTML:e,$}=a,q=finaleState(s),serial=q.commissions.length,brief=COMMISSIONS[serial%3],u=s.party.find(u=>u.uid===uid);if(!u)return;const fields=[['palette','Choose the colour story',[['river','River blues and greens'],['sunset','Sunset gold and red'],['earth','Earth and mineral tones']]],['shape','Choose the composition',[['open','An open, quiet space'],['gather','Lights gathered together'],['rise','Strong rising forms']]],['tool','Choose the technique',[['wash','Flowing pigment wash'],['stamp','Layered partner impressions'],['etch','Careful etched lines']]]];const field=fields.find(([key])=>!choices[key]);if(!field)return;const [key,title,options]=field;openModal(brief.title,`<p>The gallery asks for <b>${e(brief.title.toLowerCase())}</b>. ${e(u.nickname||u.species.name)} waits beside the canvas.</p><img class="finale-artist-portrait" src="${a.art(u)}" alt="${e(u.species.name)}"><p>${title}</p><div class="learning-choices">${options.map(([v,label])=>`<button data-fn-choice="${v}">${label}</button>`).join('')}</div>`);document.querySelectorAll('[data-fn-choice]').forEach(b=>b.onclick=()=>{const next={...choices,[key]:b.dataset.fnChoice};if(Object.keys(next).length<3){commissionChoices(a,uid,next);return;}let work;if(!a.rewardTransaction(()=>{if(finaleState(s).commissions.length===serial)work=createCommission(s,uid,next);})||!work)return;showWork(a,work);});}
function showWork(a,w){const {openModal,escapeHTML:e}=a;const medium={river:'water',sunset:'fire',earth:'steel'}[w.palette];openModal(w.title,`<div class="finale-work-frame" data-composition="${w.shape}" data-technique="${w.tool}"><img class="finale-painting" src="assets/finale/gallery-${medium}.webp" alt="${e(w.title)} by ${e(w.artist)}"><img class="finale-artist-seal" src="${a.art({species:{id:w.speciesId}})}" alt="${e(w.artist)}’s signature mark"></div><p><b>${e(w.artist)}</b> · ${e(w.tool)} · ${e(w.shape)} composition${w.partnerAffinity?' · Natural colour affinity (+100 doubloons)':''}</p><p>${w.score===3?'The curator finds every part of the brief in it.':w.score===2?'The curator recognises the brief and your partner’s own choices.':'The curator makes space for a more personal interpretation.'} Commission paid: ${w.reward} doubloons.</p><p>The work is saved in your expedition collection.</p><button id="fn-next-work" class="primary">View collection</button>`);a.$('#fn-next-work').onclick=()=>showCollection(a);a.buildMarkers();}
function showCollection(a){const q=finaleState(a.state);a.openModal('Your expedition’s artwork',`<p>${q.commissions.length} completed works. Each belongs to the partner who made it.</p><div class="learning-choices">${q.commissions.map(w=>`<button data-fn-work="${w.id}">${a.escapeHTML(w.title)} · ${a.escapeHTML(w.artist)}</button>`).join('')||'<p>Visit the gallery’s commission table to begin.</p>'}</div>`);document.querySelectorAll('[data-fn-work]').forEach(b=>b.onclick=()=>showWork(a,q.commissions.find(w=>w.id===b.dataset.fnWork)));}
export function finaleFateMenu(a){const {state:s,openModal,closeModal,line,showDialogue,escapeHTML:e,$}=a,id=s.pendingFate?.id,t=FINALE_TRAINERS.find(t=>t.id===id);if(!t||!id.startsWith('LDR-0')||!['LDR-07','LDR-08'].includes(id))return false;const choose=fate=>{let settled=false;if(!a.rewardTransaction(()=>{settled=settleFinalLeader(s,id,fate);if(settled)a.settleLeaderRewards(s,t,a.create);})||!settled)return;closeModal();a.buildMarkers();const lines=id==='LDR-07'?(fate==='SPARED'?[line('Aimon','I came here wanting someone to pay. I’m still angry. But I don’t want to keep doing this to people.','CHR-AIMON'),line(t.name,'Then I will answer for what I have ordered. The studios and the ceasefire watch remain open.','LDR-07')]:[line('Aimon','Every one of you has an explanation. I can’t listen to another one.','CHR-AIMON'),line('Cayfen','The order is carried out. The square falls quiet. Aimon finds that his anger has not gone with it.'),line('Walter','I’ll stay with you. But this is something we will have to face as well.','CHR-AERIC')]):[line('Ramelle',fate==='SPARED'?'Hasan lays his staff aside. He leads you to the old stair and gives the custodian the order to open it.':'Hasan’s death is entered in the city record. His custodian carries out the promise already made: the old stair remains open.'),line('Aimon','Under the fortress. You said you would show me.','CHR-AIMON')];lines.push(line('The mirror records',id==='LDR-07'?'The answer lies with Hasan in Ramelle. The road crosses Sporefall Chasm.':'The old stair at the east side of this hall leads below the fortress.'));showDialogue(lines,id==='LDR-08'?()=>void a.descent(fate):undefined);};
 openModal(t.name+' has yielded',`<p>${id==='LDR-07'?'Ibrahim opens a road ledger: “There is a mirror beneath Hasan’s fortress in Ramelle. I have heard people answer it. I cannot tell you who answered back.”':'Hasan shows you the old stair before returning to the formal judgement. His custodian now knows your name and the promise made to you.'}</p><p>${a.decisionHTML(t)}</p><div class="modal-actions"><button id="fn-spare" class="primary">Spare</button><button id="fn-execute">Execute</button></div>`);$('#close-modal').hidden=true;$('#fn-spare').onclick=()=>choose('SPARED');$('#fn-execute').onclick=()=>{openModal('Confirm execution',`<p>Give the permanent order to execute ${e(t.name)}?</p><button id="fn-reconsider" class="primary">Reconsider</button><button id="fn-confirm">Give the order</button>`);$('#close-modal').hidden=true;$('#fn-reconsider').onclick=()=>finaleFateMenu(a);$('#fn-confirm').onclick=()=>choose('EXECUTED');};return true;}
